#include "stdafx.h"#include "HcdElementBase.h"struct SMUL_P{#include "PrivateVars/MUL.h"};class KMUL : public KHcdElementBase  , protected SMUL_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _MUL("MUL", KMUL::Create);IHcdElement *KMUL::Create(){  return new KMUL;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KMUL, 3 )void KMUL::InitParm(){#include "PrivateVars/MUL.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KMUL::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KMUL::StepCalc( SStepCalcParams &params ){  OUTD0 = INU0 * INL0;}